async def test_a_redirect_is_never_followed(async_client: AsyncTungo, server: MockServer) -> None:
    other = MockServer()
    try:
        elsewhere = Reply(status=302, headers={"Location": other.url + "/elsewhere"})
        server.add("GET", COMPANY, elsewhere)
        server.add("POST", COMPANY + "/chat", Reply(status=307, headers={"Location": other.url + COMPANY + "/chat"}))
        server.add("GET", "/v1/companies", Reply(status=302, headers={"Location": "/v1/moved"}))
        with pytest.raises(tungoai.APIError) as caught:
            await async_client.companies.get("co_1")
        assert caught.value.status == 302
        with pytest.raises(tungoai.APIError) as streamed:
            await async_client.chat.create_stream("co_1", message="?")
        assert streamed.value.status == 307
        with pytest.raises(tungoai.APIError) as same_origin:
            await async_client.companies.list()
        assert same_origin.value.status == 302
        assert other.requests == [], "the API key must not travel to another host"
        assert [request.path for request in server.requests] == [COMPANY, COMPANY + "/chat", "/v1/companies"]
    finally:
        other.close()


