async def test_an_error_response_becomes_a_typed_error(async_client: AsyncTungo, server: MockServer) -> None:
    body = error_body(
        "invalid_request_error",
        "Проверьте поля запроса.",
        "validation_failed",
        fields=[{"path": "bin", "code": "invalid_format", "message": "БИН/ИИН — 12 цифр"}],
        hint="extra detail",
    )
    server.add(
        "GET",
        COMPANY,
        Reply(status=400, json=body, headers={"x-request-id": "req_header"}),
    )
    with pytest.raises(tungoai.InvalidRequestError) as caught:
        await async_client.companies.get("co_1")
    error = caught.value
    assert isinstance(error, tungoai.APIError)
    assert isinstance(error, tungoai.TungoError)
    assert (error.status, error.type, error.code) == (
        400,
        "invalid_request_error",
        "validation_failed",
    )
    assert (error.message, error.request_id) == ("Проверьте поля запроса.", "req_body")
    assert [(item.path, item.code, item.message) for item in error.fields] == [
        ("bin", "invalid_format", "БИН/ИИН — 12 цифр")
    ]
    assert error.extra == {"hint": "extra detail"}
    assert error.headers["x-request-id"] == "req_header"
    assert error.error is not None
    assert error.error.message == "Проверьте поля запроса."
    assert "Проверьте поля запроса." in str(error)
    assert "req_body" in str(error)


