async def test_chat_turns_have_a_long_default_timeout(server: MockServer) -> None:
    async with AsyncTungo(api_key=API_KEY, base_url=server.url) as client:
        chat = RequestSpec(method="POST", path="/x", long_running=True)
        plain = RequestSpec(method="POST", path="/x")
        assert client._total_timeout(chat, {}) == 600.0 == tungoai.DEFAULT_LONG_TIMEOUT
        assert client._total_timeout(plain, {}) == 60.0
        assert client._total_timeout(chat, {"timeout": 5}) == 5
        shorter = client.with_options(timeout=30)
        assert shorter._total_timeout(plain, {}) == 30
        assert shorter._total_timeout(chat, {}) == 600.0, "the ordinary timeout does not shorten a chat turn"
        assert shorter.long_running_timeout == 600.0
        tuned = shorter.with_options(long_running_timeout=900)
        assert (tuned._total_timeout(chat, {}), tuned._total_timeout(plain, {})) == (900, 30)
        assert client.with_options(timeout=None)._total_timeout(chat, {}) == 600.0
        assert client.with_options(long_running_timeout=None)._total_timeout(chat, {}) is None
    async with AsyncTungo(api_key=API_KEY, base_url=server.url, timeout=30, long_running_timeout=120) as client:
        assert (client._total_timeout(chat, {}), client._total_timeout(plain, {})) == (120, 30)


