async def test_iterating_a_page_walks_every_page_lazily(async_client: AsyncTungo, server: MockServer) -> None:
    path = COMPANY + "/proposals"
    server.add(
        "GET",
        path,
        Reply(json=page_body(["p1", "p2"], "cursor-2")),
        Reply(json=page_body(["p3"], "cursor-3")),
        Reply(json=page_body([], None)),
    )
    page = await async_client.proposals.list("co_1", limit=2, request_options={"headers": {"X-Trace": "t"}})
    assert isinstance(page, AsyncCursorPage)
    assert isinstance(page.body, ProposalPage)
    assert (
        [item.id for item in page.data],
        page.next_cursor,
        page.has_next_page(),
    ) == (["p1", "p2"], "cursor-2", True)
    assert len(server.requests) == 1, "nothing is fetched before it is needed"
    seen: list[str] = []
    async for item in page:
        seen.append(item.id)
        if len(seen) == 2:
            assert len(server.requests) == 1
    assert seen == ["p1", "p2", "p3"]
    assert [request.query for request in server.requests] == [
        [("limit", "2")],
        [("limit", "2"), ("cursor", "cursor-2")],
        [("limit", "2"), ("cursor", "cursor-3")],
    ]
    assert all(request.headers["x-trace"] == "t" for request in server.requests), "the options follow to every page"


