async def test_wait_for_run_gives_up_after_the_timeout(async_client: AsyncTungo, server: MockServer) -> None:
    server.add("GET", COMPANY + "/automations/runs/run_1", Reply(json=run_body("running")))
    started = time.monotonic()
    with pytest.raises(tungoai.WaitTimeoutError, match="run_1") as caught:
        await async_client.wait_for_run("co_1", "run_1", timeout=0.3, poll_interval=0.05)
    assert isinstance(caught.value, TimeoutError)
    assert 0.25 <= time.monotonic() - started < 3
    with pytest.raises(tungoai.ConfigError):
        await async_client.wait_for_run("co_1", "run_1", timeout=0)


def test_the_wait_helpers_wait_ten_minutes_by_default() -> None:
    for helper in (AsyncTungo.wait_for_run, AsyncTungo.wait_for_batch, AsyncTungo.run_scenario_and_wait):
        assert inspect.signature(helper).parameters["timeout"].default == 600.0


