async def test_wait_for_batch(async_client: AsyncTungo, server: MockServer) -> None:
    running = {**fixture("getCompanyBatch"), "id": "b_1", "running": True}
    server.add(
        "GET",
        COMPANY + "/batch/b_1",
        Reply(json=running),
        Reply(json={**running, "running": False}),
    )
    job = await async_client.wait_for_batch("co_1", "b_1", poll_interval=0.01)
    assert job.running is False
    assert len(server.requests) == 2
    server.add("GET", COMPANY + "/batch/b_1", Reply(json=running))
    with pytest.raises(tungoai.WaitTimeoutError):
        await async_client.wait_for_batch("co_1", "b_1", timeout=0.2, poll_interval=0.05)


def test_verify_webhook_uses_the_secret_of_the_client() -> None:
    secret = "whsec_" + base64.b64encode(b"0123456789abcdef").decode()
    body = b'{"id":"evt_1","type":"brand.new_event","created_at":"2026-11-09T15:00:00Z","data":{"x":1}}'
    stamp = str(int(time.time()))
    digest = hmac.new(b"0123456789abcdef", b"msg_1." + stamp.encode() + b"." + body, hashlib.sha256).digest()
    headers = {
        "Webhook-Id": "msg_1",
        "Webhook-Timestamp": stamp,
        "Webhook-Signature": "v1," + base64.b64encode(digest).decode(),
    }
    client = AsyncTungo(api_key=API_KEY, webhook_secret=secret)
    event = client.verify_webhook(body, headers)
    assert isinstance(event, tungoai.UnknownVariant), "an event type added later is still delivered"
    assert event.to_dict()["data"] == {"x": 1}
    with pytest.raises(tungoai.WebhookVerificationError) as caught:
        client.verify_webhook(body + b" ", headers)
    assert caught.value.reason == "signature_mismatch"
    with pytest.raises(tungoai.ConfigError):
        AsyncTungo(api_key=API_KEY).verify_webhook(body, headers)
